"""Tests for EnvironmentSecretInfo.scope round-trip from API payloads."""

from __future__ import annotations

from osmosis_ai.platform.api.models import (
    EnvironmentSecretInfo,
    PaginatedEnvironmentSecrets,
)


def test_environment_secret_info_parses_scope() -> None:
    info = EnvironmentSecretInfo.from_dict(
        {
            "id": "sec_1",
            "name": "OPENAI_API_KEY",
            "created_at": "2026-05-01T00:00:00Z",
            "updated_at": "2026-05-01T00:00:01Z",
            "creator_name": "Ada",
            "scope": "user",
        }
    )
    assert info.scope == "user"


def test_environment_secret_info_scope_defaults_to_none_when_absent() -> None:
    info = EnvironmentSecretInfo.from_dict({"id": "sec_1", "name": "X"})
    assert info.scope is None


def test_paginated_environment_secrets_parses_scope_per_item() -> None:
    page = PaginatedEnvironmentSecrets.from_dict(
        {
            "environment_secrets": [
                {"id": "a", "name": "A", "scope": "workspace"},
                {"id": "b", "name": "B", "scope": "user"},
            ],
            "total_count": 2,
            "has_more": False,
        }
    )
    assert [s.scope for s in page.environment_secrets] == ["workspace", "user"]

"""Tests that verify each auth error state produces the correct user-facing message.

These are integration-style tests: they call the CLI entry point and check
stderr output, ensuring the exception type -> main.py handler -> message chain
is correct end-to-end.
"""

from __future__ import annotations

from unittest.mock import patch

import pytest

from osmosis_ai.cli.errors import CLIError
from osmosis_ai.platform.auth.platform_client import (
    AuthenticationExpiredError,
)
from osmosis_ai.platform.constants import MSG_ENV_TOKEN_INVALID


class TestPlatformRequestMessages:
    """Test platform_request() error messages for each failure mode."""

    @patch(
        "osmosis_ai.platform.auth.platform_client.load_credentials", return_value=None
    )
    def test_no_credentials_does_not_say_expired(self, _mock: object) -> None:
        from osmosis_ai.platform.auth.platform_client import platform_request

        with pytest.raises(CLIError, match="Not logged in") as exc_info:
            platform_request("/api/test")
        assert exc_info.value.code == "AUTH_REQUIRED"


class TestMainExceptionHandlerMessages:
    """Test that main() maps exceptions to the correct stderr output."""

    @patch("osmosis_ai.cli.main._registered", True)
    def test_cli_error_shows_message_directly(
        self, capsys: pytest.CaptureFixture[str]
    ) -> None:
        from osmosis_ai.cli.main import main

        with patch(
            "osmosis_ai.cli.main.app",
            side_effect=CLIError(
                "This command requires an Osmosis workspace directory."
            ),
        ):
            code = main([])

        assert code == 1
        assert "Osmosis workspace directory" in capsys.readouterr().err

    @patch("osmosis_ai.cli.main._registered", True)
    def test_cli_error_preserves_bracketed_section_names(
        self, capsys: pytest.CaptureFixture[str]
    ) -> None:
        from osmosis_ai.cli.main import main

        with patch(
            "osmosis_ai.cli.main.app",
            side_effect=CLIError("Missing [experiment] section in train.toml"),
        ):
            code = main([])

        assert code == 1
        assert "Missing [experiment] section" in capsys.readouterr().err

    @patch("osmosis_ai.cli.main._registered", True)
    def test_auth_expired_shows_session_expired(
        self, capsys: pytest.CaptureFixture[str]
    ) -> None:
        from osmosis_ai.cli.main import main

        with patch(
            "osmosis_ai.cli.main.app",
            side_effect=AuthenticationExpiredError(),
        ):
            code = main([])

        assert code == 1
        captured = capsys.readouterr().err
        assert "session has expired" in captured.lower()

    @patch("osmosis_ai.cli.main._registered", True)
    def test_auth_expired_preserves_env_token_guidance(
        self, capsys: pytest.CaptureFixture[str]
    ) -> None:
        from osmosis_ai.cli.main import main

        with patch(
            "osmosis_ai.cli.main.app",
            side_effect=AuthenticationExpiredError(MSG_ENV_TOKEN_INVALID),
        ):
            code = main([])

        assert code == 1
        captured = capsys.readouterr().err
        assert "OSMOSIS_TOKEN environment variable is invalid or expired" in captured
        assert "unset OSMOSIS_TOKEN" in captured

"""Tests for separate secrets table rendering and missing-secret error enrichment."""

from __future__ import annotations

import osmosis_ai.platform.cli.shared_submit as shared_submit
from osmosis_ai.platform.api.models import (
    EnvironmentSecretInfo,
    PaginatedEnvironmentSecrets,
)


def test_fetch_secret_scopes_collects_all_pages_and_partitions(monkeypatch) -> None:
    calls: list[dict] = []

    class FakeClient:
        def list_environment_secrets(
            self, *, limit, offset, scope, credentials, git_identity
        ):
            calls.append({"scope": scope, "offset": offset})
            if offset == 0:
                return PaginatedEnvironmentSecrets(
                    environment_secrets=[
                        EnvironmentSecretInfo(id="A", name="A", scope="workspace")
                    ],
                    total_count=2,
                    has_more=True,
                    next_offset=1,
                )
            return PaginatedEnvironmentSecrets(
                environment_secrets=[
                    EnvironmentSecretInfo(id="B", name="B", scope="user")
                ],
                total_count=2,
                has_more=False,
            )

    result = shared_submit._fetch_secret_scopes(
        FakeClient(), credentials=object(), git_identity="acme/x"
    )
    assert result == ({"A"}, {"B"})
    assert all(c["scope"] == "all" for c in calls)


def test_fetch_secret_scopes_returns_none_on_error(monkeypatch) -> None:
    class FakeClient:
        def list_environment_secrets(self, **kwargs):
            raise RuntimeError("network down")

    result = shared_submit._fetch_secret_scopes(
        FakeClient(), credentials=object(), git_identity="acme/x"
    )
    assert result is None


def test_missing_secret_message_lists_set_commands() -> None:
    msg = shared_submit._missing_secret_message(["OPENAI_API_KEY", "WANDB_API_KEY"])
    assert "Could not find secret(s): OPENAI_API_KEY, WANDB_API_KEY" in msg
    assert "osmosis secret set OPENAI_API_KEY" in msg
    assert "osmosis secret set WANDB_API_KEY" in msg
    assert "Secrets default to personal scope" in msg
    assert "--scope workspace" in msg


def test_enrich_missing_secret_error_adds_hint() -> None:
    from osmosis_ai.platform.auth.platform_client import PlatformAPIError

    exc = PlatformAPIError(
        "Secret(s) not found: OPENAI_API_KEY, WANDB_API_KEY",
        404,
        details={
            "error": "Secret(s) not found: OPENAI_API_KEY, WANDB_API_KEY",
            "platform_url": "https://platform.example.test/my-workspace/secrets",
        },
    )
    enriched = shared_submit._enrich_missing_secret_error(exc)
    assert enriched is not None
    msg = str(enriched)
    assert "osmosis secret set OPENAI_API_KEY" in msg
    assert "osmosis secret set WANDB_API_KEY" in msg
    assert "Secrets default to personal scope" in msg
    assert "--scope workspace" in msg
    assert "https://platform.example.test/my-workspace/secrets" in msg


def test_enrich_missing_secret_error_reads_legacy_error_field() -> None:
    from osmosis_ai.platform.auth.platform_client import PlatformAPIError

    exc = PlatformAPIError(
        "One or more secrets could not be resolved.",
        404,
        details={
            "error": "Secret(s) not found: OPENAI_API_KEY",
            "message": "One or more secrets could not be resolved.",
        },
    )
    enriched = shared_submit._enrich_missing_secret_error(exc)
    assert enriched is not None
    assert "osmosis secret set OPENAI_API_KEY" in str(enriched)


def test_enrich_missing_secret_error_returns_none_for_other_errors() -> None:
    from osmosis_ai.platform.auth.platform_client import PlatformAPIError

    exc = PlatformAPIError("Some other error", 500)
    assert shared_submit._enrich_missing_secret_error(exc) is None
